def grid_at(lines,i,h,w):
    rows=[]
    for line in lines[i+1:i+1+h]:
        vals=[int(x) for x in line.split()]
        if len(vals)!=w: raise ValueError((i,line,len(vals),w))
        rows.append(vals)
    return rows
def extract(text):
    lines=text.splitlines(); demos=[]; test=None
    for i,line in enumerate(lines):
        if line.startswith("Demo pair ") and " input (" in line:
            dim=line.split(" input (")[1].split(")")[0]; h,w=map(int,dim.split("x")); inp=grid_at(lines,i,h,w)
            out=None
            for j in range(i+h+1,len(lines)):
                if line.startswith("Demo pair ") and False: pass
                if lines[j].startswith("Demo pair ") and " output (" in lines[j]:
                    od=lines[j].split(" output (")[1].split(")")[0]; oh,ow=map(int,od.split("x")); out=grid_at(lines,j,oh,ow); break
            if out is not None: demos.append((inp,out))
        if line.startswith("Test input ("):
            dim=line.split("Test input (")[1].split(")")[0]; h,w=map(int,dim.split("x")); test=grid_at(lines,i,h,w)
    return demos,test
all_demos=[]; test=None
for mid,text in msgs:
