cmd = r'''python3 - <<'PY'
import sqlite3,re
c=sqlite3.connect('/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u014/system/state/hermes/state.db')
s=c.execute("select content from messages where session_id='fd811c1d-a833-4eac-92d5-cde0ace3eafe' and id=1246").fetchone()[0]
for label in ('Demo pair 2 input','Test input'):
 m=re.search(re.escape(label)+r' \((\d+)x(\d+)\):\n',s); h,w=map(int,m.groups()); lines=s[m.end():].splitlines()[:h]; g=[[int(x) for x in row.split()] for row in lines]
 print('\n',label,len(g),len(g[0]))
 for conn in (4,8):
  seen=set(); comps=[]
  for r in range(len(g)):
   for col in range(len(g[0])):
    if not g[r][col] or (r,col) in seen: continue
    stack=[(r,col)]; seen.add((r,col)); pts=[]
    while stack:
     y,x=stack.pop();pts.append((y,x)); ds=[(-1,0),(1,0),(0,-1),(0,1)]
     if conn==8: ds += [(-1,-1),(-1,1),(1,-1),(1,1)]
     for dy,dx in ds:
      q=(y+dy,x+dx)
      if 0<=q[0]<len(g) and 0<=q[1]<len(g[0]) and g[q[0]][q[1]] and q not in seen: seen.add(q);stack.append(q)
    ys=[p[0] for p in pts]; xs=[p[1] for p in pts]; comps.append((len(pts),(min(ys),min(xs),max(ys),max(xs))))
  print(conn,sorted(comps,reverse=True))
 print('rows')
 for r,row in enumerate(g):
  if any(row): print(r,''.join(str(x) for x in row))
PY'''
r=terminal(cmd,timeout=180,workdir='/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u014/system/state/workspace')
print(r['output'])

