import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u014/system/state/hermes/state.db'
c=sqlite3.connect(p); sid='fd811c1d-a833-4eac-92d5-cde0ace3eafe'
for mid in [5,1246]:
 s=c.execute('select content from messages where id=?',(mid,)).fetchone()[0]
 for k in [1,2]:
  m=re.search(rf'Demo pair {k} input \(\d+x\d+\):\n(.*?)(?=\nDemo pair {k} output)',s,re.S)
  o=re.search(rf'Demo pair {k} output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|\Z)',s,re.S)
  if m:
   grid=[[int(x) for x in row.split()] for row in m.group(1).strip().splitlines()]
   out=[[int(x) for x in row.split()] for row in o.group(1).strip().splitlines()]
   print('DEMO',k,'dims',len(grid),len(grid[0]),'out',out)
   # nonzero bbox component bbox collection 8 neighbors, print component bounding boxes
   h,w=len(grid),len(grid[0]); seen=set(); comps=[]
   for r in range(h):
    for col in range(w):
     if grid[r][col] and (r,col) not in seen:
      st=[(r,col)];seen.add((r,col));pts=[]
      while st:
       y,x=st.pop();pts.append((y,x))
       for dy in [-1,0,1]:
        for dx in [-1,0,1]:
         q=(y+dy,x+dx)
         if 0<=q[0]<h and 0<=q[1]<w and grid[q[0]][q[1]] and q not in seen:
          seen.add(q);st.append(q)
      comps.append(pts)
   print('components',[(len(q),min(y for y,x in q),max(y for y,x in q),min(x for y,x in q),max(x for y,x in q)) for q in comps])
   # consider two likely clusters by bbox and compare aligned binary nonzero masks for all pairs of equal bbox dims
   for i,a in enumerate(comps):
    for j,b in enumerate(comps[i+1:],i+1):
     ra0,ra1=min(y for y,x in a),max(y for y,x in a);ca0,ca1=min(x for y,x in a),max(x for y,x in a)
     rb0,rb1=min(y for y,x in b),max(y for y,x in b);cb0,cb1=min(x for y,x in b),max(x for y,x in b)
     if (ra1-ra0,ca1-ca0)==(rb1-rb0,cb1-cb0):
      dif=[]
      for y in range(ra1-ra0+1):
       for x in range(ca1-ca0+1):
        va=grid[ra0+y][ca0+x]!=0;vb=grid[rb0+y][cb0+x]!=0
        if va!=vb:dif.append((y,x))
      if dif:
       print('pair',i,j,'same-shape diff n,bbox',len(dif),(min(y for y,x in dif),max(y for y,x in dif),min(x for y,x in dif),max(x for y,x in dif)))

