import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u014/system/state/hermes/state.db'; c=sqlite3.connect(p)
msgs=c.execute('select content from messages where session_id=? and role="user" order by id',('fd811c1d-a833-4eac-92d5-cde0ace3eafe',)).fetchall()
items=[]
for (text,) in msgs:
 if not text: continue
 im=re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)',text)
 om=re.search(r'Demo pair (\d+) output \((\d+)x(\d+)\):\n((?:[0-9 ]+\n)+)',text)
 if im and om:
  g=[list(map(int,x.split())) for x in im.group(4).strip().splitlines()]; out=[list(map(int,x.split())) for x in om.group(4).strip().splitlines()]; items.append((g,out))
for idx,(g,out) in enumerate(items,1):
 H,W=len(g),len(g[0]); oh,ow=len(out),len(out[0]); exact=[]; top=[]
 for h in range(oh,H+1):
  for w in range(ow,W+1):
   wins=[]
   for r in range(H-h+1):
    for c0 in range(W-w+1): wins.append((r,c0,[g[r+y][c0+x] for y in range(h) for x in range(w)]))
   for i,(r1,c1,a) in enumerate(wins):
    for r2,c2,b in wins[i+1:]:
     if r1<r2+h and r2<r1+h and c1<c2+w and c2<c1+w: continue
     ds=[k for k,(x,y) in enumerate(zip(a,b)) if x!=y]
     if not ds: continue
     rr=[k//w for k in ds]; cc=[k%w for k in ds]; rlo,rhi=min(rr),max(rr); clo,chi=min(cc),max(cc)
     mask=[[0]*(chi-clo+1) for _ in range(rhi-rlo+1)]
     for k in ds: mask[k//w-rlo][k%w-clo]=8
     if mask==out: exact.append((sum(x==y and x!=0 for x,y in zip(a,b)),len(ds),h,w,(r1,c1),(r2,c2)))
     same=sum(x==y and x!=0 for x,y in zip(a,b)); score=(same/len(ds),same,-len(ds),h*w)
     top.append((score,len(ds),h,w,(r1,c1),(r2,c2), mask==out))
 print('DEMO',idx,'exact',len(exact),'best exact',sorted(exact,reverse=True)[:10])
 print('best candidates',sorted(top,reverse=True)[:5])

