import sqlite3,re
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL-hermes-luna6-high-fresh0/frozen/held-out-reference/play/users/u014/system/state/hermes/state.db'
c=sqlite3.connect(f'file:{p}?mode=ro',uri=True)
sid='fd811c1d-a833-4eac-92d5-cde0ace3eafe'
rows=c.execute("select role,content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
texts=[x[1] or '' for x in rows]
def parse(text, header):
    ix=text.index(header)+len(header)
    out=[]
    for line in text[ix:].splitlines():
        if re.fullmatch(r'\d+(?: \d+)*',line.strip()): out.append([int(x) for x in line.split()])
        else: break
    return out
pairmsg=next(t for t in texts if 'Demo pair 2 input' in t)
testmsg=next(t for t in texts if 'New instance. Task id: task-02bf8fcf' in t)
demo=parse(pairmsg,'Demo pair 2 input (25x25):\n')
out=parse(pairmsg,'Demo pair 2 output (4x8):\n')
test=parse(testmsg,'Test input (24x25):\n')
print('shapes',len(demo),{len(x) for x in demo},len(out),{len(x) for x in out},len(test),{len(x) for x in test})
