 "content": "from collections import deque


def _components(grid):
    """Return nonzero 4-connected components as (cells, bbox) pairs."""
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while queue:
                y, x = queue.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        queue.append((ny, nx))
            ys = [y for y, _ in cells]
            xs = [x for _, x in cells]
            bbox = (min(ys), max(ys) + 1, min(xs), max(xs) + 1)
            components.append((cells, bbox))
    return components


def transform(grid):
    """Compare the two nonzero objects and return their cropped difference mask."""
    components = sorted(_components(grid), key=lambda item: len(item[0]), reverse=True)
    if len(components) < 2:
        return [[0]]

    (_, (ar0, ar1, ac0, ac1)), (_, (br0, br1, bc0, bc1)) = components[:2]
    ah, aw = ar1 - ar0, ac1 - ac0
    if (ah, aw) != (br1 - br0, bc1 - bc0):
        return [[0]]

    differences = [
        (r, c)
        for r in range(ah)
        for c in range(aw)
        if grid[ar0 + r][ac0 + c] != grid[br0 + r][bc0 + c]
    ]
    if not differences:
        return [[0]]

    r0 = min(r for r, _ in differences)
    r1 = max(r for r, _ in differences)
    c0 = min(c for _, c in differences)
    c1 = max(c for _, c in differences)
    differing = set(differences)
    return [
        [8 if (r, c) in differing else 0 for c in range(c0, c1 + 1)]
        for r in range(r0, r1 + 1)
    ]


